var SIZE_UNITS=['B','KB','MB','GB','TB','PB'];
function convertSize(value, from, to, base){
  base=base||1024;
  var fi=SIZE_UNITS.indexOf(String(from||'').toUpperCase());
  var ti=SIZE_UNITS.indexOf(String(to||'').toUpperCase());
  if(fi<0||ti<0) return {ok:false, reason:'unknown unit'};
  var bytes=value*Math.pow(base,fi);
  return {ok:true, value:bytes/Math.pow(base,ti), bytes:bytes};
}

var EXPORTS={convertSize:convertSize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DataSizeForgePure = EXPORTS; }
